            await activateProject(project);

            return project;
        },
        addWorktree: async (project) => {
            if (!openWorktreeFolder) throw new Error('Worktree folder picker is not available');

            const folderPath = await openWorktreeFolder();
            if (!folderPath) return false;

            await worktreeService.add(project, folderPath);

            return true;
        },
        prepareWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree preparation request');

            return worktreeService.prepare(request.project, request.worktree, request.branchName);
        },
        commitWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree commit request');

            return worktreeService.commit(request.project, request.worktree, request.message);
        },
        discardWorktreeChanges: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree discard request');

            return worktreeService.discard(request.project, request.worktree);
        },
        integrateWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree integration request');

            return worktreeService.integrate(request.project, request.worktree);
        },
        parkWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree parking request');

            return worktreeService.park(request.project, request.worktree);
        },
        pullWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree pull request');

            return worktreeService.pull(request.project, request.worktree);
        },
        pull: (project) => worktreeService.pullPrimary(project),
        push: async (project) => {
            await localGitService.push(project);
            await worktreeService.refreshLocal();
        },
        pushWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree push request');

            return worktreeService.push(request.project, request.worktree);
        },
        rebaseWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree rebase request');

            return worktreeService.rebase(request.project, request.worktree);
        },
        onWorktreesChanged: (callback) => worktreeService.subscribe(callback),
        refreshWorktrees: (project) => worktreeService.refreshRemote(project),
        resolveProject: async (project) => {
            const resolvedProject = await localGitService.resolveLocalProject(project.rootPath);
            await activateProject(resolvedProject);

            return resolvedProject;
        },
        saveActionSchedules: (project, actionsFolder, schedules) => localGitService.saveActionSchedules(project, actionsFolder, schedules),
        saveProjectConfig: (project, config) => localGitService.saveProjectConfig(project, config),
        removeWorktree: (project, folderPath) => worktreeService.remove(project, folderPath),
        stopAgent: (runId) => agentRunnerService.stop(runId),
        watchProject: (project, callback) => localGitService.watchProject(project, (event) => {
            if (actionSchedulerService) void actionSchedulerService.handleProjectChange(event);
            callback(event);
        }),
    };

    const actionBridge = {
        answerActionQuestion: (executionId, requestId, answers) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.answerAgentQuestion(executionId, requestId, answers);
        },
        generateDiff: async (request) => {
            const result = await diffService.generateDiff(currentLocalProject, request);

            return { ...result, repositoryRoot: currentLocalProject.rootPath };
        },
        loadActionRunHistory: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            const projectFolder = actionRunnerService.requireProjectFolder();
            const historyRequest = { ...request, projectFolder };

            return localGitService.loadActionRunHistory(currentLocalProject, historyRequest);
        },
        loadActiveActionExecutionEvents: () => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.loadActiveExecutionEvents();
        },
        notifyActionCardStateChange: (cardInternalId, state) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.handleCardStateChange(cardInternalId, state);
        },
        loadCardActivity: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');
            if (!request || typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
                throw new Error('Missing card activity cardInternalId');
            }
            const projectFolder = actionRunnerService.requireProjectFolder();
            const worktrees = worktreeService.getRecords(currentLocalProject);

            return localGitService.loadCardActivity(currentLocalProject, projectFolder, request.cardInternalId, worktrees);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        cancelActionExecution: (executionId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.cancel(executionId);
        },
        finishActionExecution: (executionId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.finishAgentExecution(executionId);
        },
        onActionExecution: (callback) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.subscribe(callback);
        },
        openInEditor: async (request) => diffService.openInEditor(currentLocalProject, request),
        prepareActionPrompt: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.prepareActionPrompt(request);
        },
        readFileAtCommit: (request) => localGitService.readFileAtCommit(currentLocalProject, request),
        registerActionSchedule: (request) => {
            if (!actionSchedulerService) throw new Error('Action scheduler is not available');

            return actionSchedulerService.registerActionSchedule(request);
        },
        runSearchRegexpAgent: async (input, callback) => {
            if (typeof input !== 'string' || input.length === 0) throw new Error('Missing regular expression search input');

            const resolved = resolveSearchAgent(readDesktopConfig(desktopConfigStore));
            const projectConfig = await localGitService.loadProjectConfig(currentLocalProject);
            const projectFolder = typeof projectConfig?.projectFolder === 'string' ? projectConfig.projectFolder : '';
            const request = {
                agent: resolved.agent,
                activityOrigin: { kind: 'project' },
                activityProject: currentLocalProject,
                command: resolved.command,
                prompt: `${SEARCH_AGENT_PROMPT_PREFIX}${input}`,
                projectFolder,
                title: 'Search RegExp',
            };
            const result = await agentRunnerService.run(currentLocalProject, request, callback);

            return result.stdout;
        },
        sendActionMessage: (executionId, content) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendAgentMessage(executionId, content);
        },
        sendActionQueuedMessage: (executionId, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendQueuedAgentMessage(executionId, revision);
        },
        setActionQueuedMessage: (executionId, content, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.setAgentQueuedMessage(executionId, content, revision);
        },
        startAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request);
        },
        startUnattendedAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request, { interactive: false });
        },
    };

    const codexRuntimeBridge = {
        getCodexRateLimits: () => codexRuntimeService?.getSnapshot() ?? null,
        onCodexRateLimits: (callback) => {
            if (!codexRuntimeService) throw new Error('Codex runtime service is not available');

            return codexRuntimeService.subscribe(callback);
        },
    };

    const methods = { ...dataBridge, ...actionBridge, ...codexRuntimeBridge };

    return {
        actionBridge,
        codexRuntimeBridge,
        dataBridge,
        invoke: (method, params = []) => {
            const handler = methods[method];
            if (!handler) throw new Error(`Unknown remote-control method: ${method}`);
            if (!Array.isArray(params)) throw new Error('Remote-control params must be an array');

            return handler(...params);
        },
    };
}

module.exports = { createLocalBridgeDispatch };

const { contextBridge, ipcRenderer } = require('electron');

const CONFIG_SET_DESKTOP_CHANNEL = 'md2-config:set-desktop';
const LIFECYCLE_FLUSH_DONE_CHANNEL = 'md2-lifecycle:flush-pending-commits-done';
const LIFECYCLE_FLUSH_REQUEST_CHANNEL = 'md2-lifecycle:flush-pending-commits';
const LOCAL_BRIDGE_EVENT_CHANNEL = 'md2-local-bridge:event';
const LOCAL_BRIDGE_INVOKE_CHANNEL = 'md2-local-bridge:invoke';
const LOCAL_BRIDGE_SUBSCRIBE_CHANNEL = 'md2-local-bridge:subscribe';
const LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL = 'md2-local-bridge:unsubscribe';
const REMARKABLE_IMPORT_FILES_CHANNEL = 'md2-remarkable:import-files';
const REMARKABLE_LIST_IMAGE_FILES_CHANNEL = 'md2-remarkable:list-image-files';
const REMARKABLE_TEST_CONNECTION_CHANNEL = 'md2-remarkable:test-connection';
const REMOTE_CONTROL_GET_STATUS_CHANNEL = 'md2-remote-control:get-status';
const REMOTE_CONTROL_START_CHANNEL = 'md2-remote-control:start';
const REMOTE_CONTROL_STATUS_CHANNEL = 'md2-remote-control:status';
const REMOTE_CONTROL_STOP_CHANNEL = 'md2-remote-control:stop';
const THEME_SET_MODE_CHANNEL = 'md2-theme:set-mode';

const DATA_METHODS = [
    'addWorktree',
    'cancelActionSchedule',
    'checkoutBranch',
    'commit',
    'commitWorktree',
    'createProject',
    'deleteFile',
    'deleteFolder',
    'discardWorktreeChanges',
    'hasPendingPush',
    'integrateWorktree',
    'listBranches',
    'listAgentConversationReferences',
    'listRepositoryFiles',
    'listTopLevelFolders',
    'loadActionFiles',
    'loadActionSchedules',
    'loadAgentAvailability',
    'loadAgentConversation',
    'loadFile',
    'loadProject',
    'loadProjectAsset',
    'loadProjectConfig',
    'loadProjectRoot',
    'moveFiles',
    'openProjectFolder',
    'parkWorktree',
    'prepareWorktree',
    'pull',
    'pullWorktree',
    'push',
    'pushWorktree',
    'rebaseWorktree',
    'refreshWorktrees',
    'removeWorktree',
    'resolveProject',
    'saveActionSchedules',
    'saveProjectConfig',
    'stopAgent',
];
const ACTION_METHODS = [
    'answerActionQuestion',
    'cancelActionExecution',
    'finishActionExecution',
    'generateDiff',
    'loadActionRunHistory',
    'loadActiveActionExecutionEvents',
    'notifyActionCardStateChange',
    'loadCardActivity',
    'loadAgentAvailability',
    'openInEditor',
    'prepareActionPrompt',
    'readFileAtCommit',
    'registerActionSchedule',
    'runSearchRegexpAgent',
    'sendActionMessage',
    'sendActionQueuedMessage',
    'setActionQueuedMessage',
    'startAction',
    'startUnattendedAction',
];
const EVENT_METHODS = new Set(['runSearchRegexpAgent']);
const CODEX_RUNTIME_METHODS = ['getCodexRateLimits'];

let nextEventId = 1;
let desktopConfig = readArgumentJson('md2-desktop-config', {});

function readArgumentValue(name) {
    const prefix = `--${name}=`;
    const argument = process.argv.find((candidate) => candidate.startsWith(prefix));

    return argument ? argument.slice(prefix.length) : null;
}

function readArgumentJson(name, fallback) {
    const value = readArgumentValue(name);
    if (!value) return fallback;

    return JSON.parse(decodeURIComponent(value));
}

function createEventId(method) {
    const eventId = `${method}-${nextEventId}`;
    nextEventId += 1;

    return eventId;
}

function invokeBridge(method, params, callback) {
    const eventId = EVENT_METHODS.has(method) && callback ? createEventId(method) : null;
    let listener = null;

    if (eventId) {
        listener = (_event, message) => {
            if (message.eventId === eventId) callback(message.payload);
        };
        ipcRenderer.on(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    }

    return ipcRenderer.invoke(LOCAL_BRIDGE_INVOKE_CHANNEL, { eventId, method, params }).finally(() => {
        if (listener) ipcRenderer.removeListener(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    });
}

function subscribeBridge(method, params, callback) {
    const subscriptionId = createEventId(method);
    const listener = (_event, message) => {
        if (message.eventId === subscriptionId) callback(message.payload);
    };

    ipcRenderer.on(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    ipcRenderer.send(LOCAL_BRIDGE_SUBSCRIBE_CHANNEL, { method, params, subscriptionId });

    return () => {
        ipcRenderer.removeListener(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
        ipcRenderer.send(LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL, subscriptionId);
    };
}

function createBridge(methods) {
    return Object.fromEntries(methods.map((method) => [
        method,
        (...params) => {
            const callback = EVENT_METHODS.has(method) && typeof params[params.length - 1] === 'function'
                ? params.pop()
                : null;

            return invokeBridge(method, params, callback);
        },
    ]));
}

function exposeWarning(message) {
    const render = () => {
        document.body.innerHTML = '';
        const warning = document.createElement('main');
        warning.setAttribute('role', 'alert');
        warning.style.cssText = 'font-family: system-ui, sans-serif; padding: 24px; color: #7f1d1d;';
        warning.textContent = message;
        document.body.appendChild(warning);
    };

    if (document.body) {
        render();
        return;
    }

    window.addEventListener('DOMContentLoaded', render);
}

function isAllowedOrigin() {
    const trustedLocation = readArgumentValue('md2-bridge-trusted-location');
    if (trustedLocation) {
        const currentUrl = new URL(window.location.href);
        const trustedUrl = new URL(decodeURIComponent(trustedLocation));
        currentUrl.hash = '';
        trustedUrl.hash = '';
        if (currentUrl.href === trustedUrl.href) return true;
    }

    const allowedOrigins = readArgumentJson('md2-bridge-allowed-origins', []);

    return allowedOrigins.includes(window.location.origin);
}

if (!isAllowedOrigin()) {
    exposeWarning(`MDÂ² desktop bridges blocked for origin: ${window.location.origin}`);
} else {
    const themeBridge = { setThemeMode: (mode) => ipcRenderer.send(THEME_SET_MODE_CHANNEL, mode) };
    const lifecycleBridge = {
        confirmFlush: (requestId) => ipcRenderer.send(LIFECYCLE_FLUSH_DONE_CHANNEL, requestId),
        onFlushRequested: (callback) => {
            const listener = (_event, requestId) => callback(requestId);
            ipcRenderer.on(LIFECYCLE_FLUSH_REQUEST_CHANNEL, listener);

            return () => ipcRenderer.removeListener(LIFECYCLE_FLUSH_REQUEST_CHANNEL, listener);
        },
    };
    const configBridge = {
        getDesktopConfig: () => desktopConfig,
        setDesktopConfig: (values) => {
            desktopConfig = { ...desktopConfig, ...values };
            void ipcRenderer.invoke(CONFIG_SET_DESKTOP_CHANNEL, values);
        },
    };
    const remoteControlBridge = {
        getStatus: () => ipcRenderer.invoke(REMOTE_CONTROL_GET_STATUS_CHANNEL),
        onStatusChange: (callback) => {
            const listener = (_event, status) => callback(status);
            ipcRenderer.on(REMOTE_CONTROL_STATUS_CHANNEL, listener);

            return () => ipcRenderer.removeListener(REMOTE_CONTROL_STATUS_CHANNEL, listener);
        },
        start: () => ipcRenderer.invoke(REMOTE_CONTROL_START_CHANNEL),
        stop: () => ipcRenderer.invoke(REMOTE_CONTROL_STOP_CHANNEL),
    };
    const remarkableBridge = {
        importFiles: (request) => ipcRenderer.invoke(REMARKABLE_IMPORT_FILES_CHANNEL, request),
        listImageFiles: (settings) => ipcRenderer.invoke(REMARKABLE_LIST_IMAGE_FILES_CHANNEL, settings),
        testConnection: (settings) => ipcRenderer.invoke(REMARKABLE_TEST_CONNECTION_CHANNEL, settings),
    };
    const dataBridge = {
        ...createBridge(DATA_METHODS),
        onWorktreesChanged: (callback) => subscribeBridge('onWorktreesChanged', [], callback),
        watchProject: (project, callback) => subscribeBridge('watchProject', [project], callback),
    };
    const actionBridge = {
        ...createBridge(ACTION_METHODS),
        onActionExecution: (callback) => subscribeBridge('onActionExecution', [], callback),
    };
    const codexRuntimeBridge = {
        ...createBridge(CODEX_RUNTIME_METHODS),
        onCodexRateLimits: (callback) => subscribeBridge('onCodexRateLimits', [], callback),
    };

    contextBridge.exposeInMainWorld('md2Theme', themeBridge);
    contextBridge.exposeInMainWorld('md2Lifecycle', lifecycleBridge);
    contextBridge.exposeInMainWorld('md2Config', configBridge);
    contextBridge.exposeInMainWorld('md2RemoteControl', remoteControlBridge);
    contextBridge.exposeInMainWorld('md2Remarkable', remarkableBridge);
    contextBridge.exposeInMainWorld('md2Data', dataBridge);
    contextBridge.exposeInMainWorld('md2Actions', actionBridge);
    contextBridge.exposeInMainWorld('md2CodexRuntime', codexRuntimeBridge);
}

