    'listBranches',
    'listAgentConversationReferences',
    'listRepositoryFiles',
    'listTopLevelFolders',
    'loadActionFiles',
    'loadActionSchedules',
    'loadAgentAvailability',
    'loadAgentConversation',
    'loadFile',
    'loadProject',
    'loadProjectAsset',
    'loadProjectConfig',
    'loadProjectRoot',
    'moveFiles',
    'openProjectFolder',
    'parkWorktree',
