import { Box, Stack, Typography } from '@mui/material'
import { useEffect, useLayoutEffect, useRef, type UIEvent } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import type { AgentConversation, AgentConversationEvent, AgentConversationMessage } from '../../data/data_types'
import { useAppTheme } from '../../theme/use_app_theme'
import { buildMarkdownContentSx } from '../editor/markdown_style_sx'
import type { PopupRunStatus } from './action_popup_defaults'
import { ActionConversationLink } from './action_conversation_link'
import { actionConversationUrlTransform } from './action_conversation_url_transform'
import { actionStatusLabel } from './action_status'
import { ConversationTimer } from './conversation_timer'
import { AgentToolActivity } from './agent_tool_activity'
import { CommandExecutionActivity } from './command_execution_activity'
import { ReasoningActivity } from './reasoning_activity'
import { activityIdentity } from './activity_display'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96
const MARKDOWN_COMPONENTS = { a: ActionConversationLink }

interface ActionConversationChatProps {
    conversation: AgentConversation | null
    onConversationViewed?: (conversation: AgentConversation) => void
    status: PopupRunStatus
}

type ConversationFeedEntry =
    | { kind: 'activity', order: number, value: AgentConversationEvent }
    | { kind: 'message', order: number, value: AgentConversationMessage }

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

function isCodexConversation(conversation: AgentConversation) {
    return conversation.providerSessions.some(({ agent }) => agent === 'codex')
        || conversation.messages.some(({ agent }) => agent === 'codex')
        || conversation.events.some(({ providerItemId }) => !!providerItemId)
}

function buildConversationFeed(conversation: AgentConversation | null) {
    if (!conversation) return []
    const messages: ConversationFeedEntry[] = conversation.messages
        .filter(({ role }) => role === 'user' || role === 'assistant')
        .map((value, order) => ({ kind: 'message', order, value }))
    const activities: ConversationFeedEntry[] = isCodexConversation(conversation)
        ? conversation.events
            .filter(({ status, type }) => type !== 'reasoning' || status !== 'completed')
            .map((value, index) => ({ kind: 'activity', order: messages.length + index, value }))
        : []

    return [...messages, ...activities].sort((left, right) => {
        const leftSequence = left.value.sequence
        const rightSequence = right.value.sequence
        if (leftSequence !== undefined && rightSequence !== undefined) return leftSequence - rightSequence || left.order - right.order
        if (leftSequence !== undefined) return -1
        if (rightSequence !== undefined) return 1

        return left.order - right.order
    })
}

function renderActivity(activity: AgentConversationEvent) {
    if (activity.type === 'reasoning') return <ReasoningActivity activity={activity} />
    if (activity.type === 'commandExecution') return <CommandExecutionActivity activity={activity} />

    return <AgentToolActivity activity={activity} />
}

/** Ordered user/assistant transcript shown above the popup prompt. */
export function ActionConversationChat({ conversation, onConversationViewed, status }: ActionConversationChatProps) {
    const { markdownStyleConfig } = useAppTheme()
    const markdownContentSx = buildMarkdownContentSx(markdownStyleConfig)
    const feed = buildConversationFeed(conversation)
    const viewportRef = useRef<HTMLDivElement>(null)
    const conversationPathRef = useRef<string | null | undefined>(undefined)
    const stuckToEndRef = useRef(true)

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    useEffect(() => {
        if (!conversation?.completedAt || conversation.status === 'running' || conversation.status === 'waitingForInput') return

        onConversationViewed?.(conversation)
    }, [conversation, onConversationViewed])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const conversationPath = conversation?.path ?? null
        const conversationChanged = conversationPathRef.current !== conversationPath
        conversationPathRef.current = conversationPath
        if (conversationChanged) stuckToEndRef.current = true
        if (!stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    })

    return (
        <Stack
            aria-label="Conversation chat"
            onScroll={handleScroll}
            ref={viewportRef}
            spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}
        >
            {feed.map((entry) => entry.kind === 'message' ? (
                <Box
                    key={entry.value.id}
                    sx={{
                        alignSelf: entry.value.role === 'user' ? 'flex-end' : 'flex-start',
                        bgcolor: entry.value.role === 'user' ? 'custom.primaryBg' : 'custom.track',
                        borderRadius: 1,
                        flexShrink: 0,
                        maxWidth: '88%',
                        minWidth: 0,
                        overflowWrap: 'anywhere',
                        px: 1.25,
                        py: 1,
                        ...markdownContentSx,
                    }}
                >
                    <Box className="mdxeditor-content">
                        <ReactMarkdown
                            components={MARKDOWN_COMPONENTS}
                            remarkPlugins={[remarkGfm]}
                            urlTransform={actionConversationUrlTransform}
                        >
                            {entry.value.content}
                        </ReactMarkdown>
                    </Box>
                </Box>
            ) : (
                <Box key={activityIdentity(entry.value)} sx={{ minWidth: 0 }}>
                    {renderActivity(entry.value)}
                </Box>
            ))}
            {status !== 'idle' ? (
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', flexShrink: 0 }}>
                    <Typography color={status === 'failed' ? 'error.main' : 'text.secondary'} role="status" variant="caption">
                        {actionStatusLabel(status)}
                    </Typography>
                    {conversation ? (
                        <ConversationTimer completedAt={conversation.completedAt} startedAt={conversation.startedAt} />
                    ) : null}
                </Stack>
            ) : null}
        </Stack>
    )
}

import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { actionService } from '../../services/actions/action_service'
import { dataService } from '../../services/data/data_service'
import { workspaceNavigationService } from '../../services/project/workspace_navigation_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'

const ABSOLUTE_WINDOWS_PATH_PATTERN = /^[a-z]:\//iu
const FILE_URL_PATTERN = /^file:\/+/iu
const URL_SCHEME_PATTERN = /^[a-z][a-z\d+.-]*:/iu

function decodeLinkPath(href: string) {
    try {
        return decodeURIComponent(href)
    } catch {
        throw new Error(`Invalid local file link: ${href}`)
    }
}

function normalizePathSegments(path: string, allowDrive: boolean) {
    const normalizedPath = path.replace(/\\/gu, '/')
    const drive = allowDrive && ABSOLUTE_WINDOWS_PATH_PATTERN.test(normalizedPath)
        ? normalizedPath.slice(0, 2)
        : ''
    const pathWithoutDrive = drive ? normalizedPath.slice(2) : normalizedPath
    const segments: string[] = []
    for (const segment of pathWithoutDrive.split('/')) {
        if (!segment || segment === '.') continue
        if (segment === '..') {
            if (segments.length === 0) throw new Error('Local file link points outside the active repository')
            segments.pop()
            continue
        }
        segments.push(segment)
    }

    return drive ? `${drive}/${segments.join('/')}` : segments.join('/')
}

function fileUrlPath(href: string) {
    if (!FILE_URL_PATTERN.test(href)) return href

    const path = href.replace(FILE_URL_PATTERN, '')

    return path.startsWith('/') && ABSOLUTE_WINDOWS_PATH_PATTERN.test(path.slice(1)) ? path.slice(1) : path
}

function isPathInsideFolder(path: string, folder: string) {
    if (!folder) return true

    return path.toLowerCase().startsWith(`${folder.toLowerCase()}/`)
}

/** True when a Markdown href represents a repository file rather than normal browser navigation. */
export function isLocalFileLink(href: string) {
    const normalizedHref = href.trim().replace(/\\/gu, '/')
    if (!normalizedHref || normalizedHref.startsWith('#') || normalizedHref.startsWith('/') || normalizedHref.startsWith('//')) return false
    if (ABSOLUTE_WINDOWS_PATH_PATTERN.test(normalizedHref) || FILE_URL_PATTERN.test(normalizedHref)) return true

    return !URL_SCHEME_PATTERN.test(normalizedHref)
}

/** Resolve a chat link to the canonical repository-relative path from the loaded file index. */
export function resolveActionConversationLinkPath(href: string, repositoryRoot: string, repositoryFiles: readonly string[]) {
    if (!repositoryRoot) throw new Error('Cannot open a local file link without an active repository path')

    const decodedPath = fileUrlPath(decodeLinkPath(href.trim())).replace(/\\/gu, '/')
    const normalizedRoot = normalizePathSegments(repositoryRoot, true).replace(/\/+$/u, '')
    const normalizedTarget = normalizePathSegments(decodedPath, true)
    let relativePath = normalizedTarget
    if (ABSOLUTE_WINDOWS_PATH_PATTERN.test(normalizedTarget)) {
        const normalizedRootLower = normalizedRoot.toLowerCase()
        const normalizedTargetLower = normalizedTarget.toLowerCase()
        if (!normalizedTargetLower.startsWith(`${normalizedRootLower}/`)) {
            throw new Error('Local file link points outside the active repository')
        }
        relativePath = normalizedTarget.slice(normalizedRoot.length + 1)
    }
    const canonicalPath = repositoryFiles.find((candidate) => (
        normalizePathSegments(candidate, false).toLowerCase() === relativePath.toLowerCase()
    ))
    if (!canonicalPath) throw new Error(`Local file link target does not exist: ${relativePath}`)

    return canonicalPath.replace(/\\/gu, '/')
}

/** Open one validated local chat link in the internal list editor or VS Code. */
export async function openActionConversationLink(href: string) {
    const { project, snapshot } = dataService.getState()
    if (!project || !snapshot) throw new Error('Cannot open a local file link before a project is loaded')

    const repositoryPath = resolveActionConversationLinkPath(href, project.rootPath ?? '', snapshot.repositoryFiles)
    const projectFolder = normalizePathSegments(dataService.getConfig()?.projectFolder ?? '', false)
    const isProjectMarkdown = isPathInsideFolder(repositoryPath, projectFolder) && repositoryPath.toLowerCase().endsWith('.md')
    const isLoadedProjectAction = isPathInsideFolder(repositoryPath, projectFolder)
        && actionService.getActionByPath(repositoryPath) !== null
    if (isProjectMarkdown || isLoadedProjectAction) {
        workspaceViewService.setViewMode('text')
        workspaceNavigationService.open(repositoryPath)
        return
    }

    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Opening local project files in VS Code requires Electron local mode')

    await bridge.openInEditor({ line: 1, path: repositoryPath })
}

