import { register } from '.././service_injector'

export interface WorkspaceOpenRequest {
    path: string
}

/**
 * Decouples the shell (search, and future callers) from the workspace view. Callers ask to open a
 * card/file by path; `ProjectWorkspace` subscribes and reveals it without changing the current view mode.
 */
export class WorkspaceNavigationService extends EventTarget {
    constructor() {
        super()
        register('workspaceNavigationService', this)
    }

    /** Requests that the workspace reveal the card or file at `path`. */
    open(path: string) {
        if (!path) throw new Error('Cannot open a workspace path without a path')

        this.dispatchEvent(new CustomEvent<WorkspaceOpenRequest>('open', { detail: { path } }))
    }
}

export const workspaceNavigationService = new WorkspaceNavigationService()

import type { ActionDefinition } from '../data/action_types'
import type { ProjectCard, ProjectReference, ProjectSnapshot } from '../data/data_types'
import { ACTIONS_CHANGED_EVENT, ACTION_DRAFT_CHANGED_EVENT } from './actions/action_service_events'
import { register } from './service_injector'
import { ManagedOpenDocument } from './managed_open_document'
import type {
    CardOpenDocument,
    OpenDocument,
    OpenDocumentChangedDetail,
    OpenDocumentDraft,
    OpenDocumentObject,
} from './open_document'

export type {
    ActionOpenDocument,
    CardOpenDocument,
    OpenDocument,
    OpenDocumentChangedDetail,
    OpenDocumentDraft,
    OpenDocumentObject,
    OpenDocumentOrigin,
    OpenDocumentSaveReference,
} from './open_document'

export interface OpenDocumentEventDetail {
    document: OpenDocument
}

export interface OpenFilesSnapshot {
    activeDocument: OpenDocument | null
    documents: readonly OpenDocument[]
}

interface OpenFilesDependencies {
    actionService: EventTarget & Pick<import('./actions/action_service').ActionService, 'getActions' | 'draftStore'>
    dataService: EventTarget & Pick<import('./data/data_service').DataService, 'getState'>
}

const EMPTY_SNAPSHOT: OpenFilesSnapshot = { activeDocument: null, documents: [] }

function isProjectCard(object: OpenDocumentObject): object is ProjectCard {
    return 'header' in object
}

function isCardDraft(draft: OpenDocumentDraft): draft is ProjectCard {
    return 'header' in draft
}

/** Cards are identified by their stable internal ID; regular markdown files have none and use their path. */
function documentIdentity(object: OpenDocumentObject) {
    if (!isProjectCard(object)) return object.id

    return object.header.internalId ?? object.path
}

function projectKey(project: ProjectReference | null) {
    return project ? `${project.id}:${project.branch}` : null
}

function snapshotObjects(snapshot: ProjectSnapshot | null, actions: ActionDefinition[]) {
    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return [...cards, ...actions]
}

function objectPath(object: OpenDocumentObject) {
    if (isProjectCard(object)) return object.path
    return object.sourcePath
}

type ManagedDocument = ManagedOpenDocument & OpenDocument

function renewManagedDocument(document: ManagedDocument, object: OpenDocumentObject, draft: OpenDocumentDraft) {
    if (document.kind === 'card' && isProjectCard(object) && isCardDraft(draft)) {
        document.renew(documentIdentity(object), object, draft)
        return
    }
    if (document.kind === 'action' && !isProjectCard(object) && !isCardDraft(draft)) {
        document.renew(documentIdentity(object), object, draft)
        return
    }

    throw new Error(`Cannot renew open ${document.kind} document with a different object kind`)
}

/** Owns canonical open documents and their list/board memberships. */
export class OpenFilesService extends EventTarget {
    private actionService: OpenFilesDependencies['actionService'] | null = null
    private readonly boardDocuments = new Set<ManagedDocument>()
    private dataService: OpenFilesDependencies['dataService'] | null = null
    private readonly registeredDocuments = new Map<string, ManagedDocument>()
    private loadedProjectKey: string | null = null
    private registryScopeRevision = 0
    private snapshot = EMPTY_SNAPSHOT

    constructor() {
        super()
        register('openFilesService', this)
    }

    init(dependencies: OpenFilesDependencies) {
        if (this.actionService === dependencies.actionService && this.dataService === dependencies.dataService) return

        this.actionService?.removeEventListener(ACTIONS_CHANGED_EVENT, this.handleActionChanged)
        this.actionService?.removeEventListener(ACTION_DRAFT_CHANGED_EVENT, this.handleActionChanged)
        this.dataService?.removeEventListener('changed', this.handleDataChanged)
        this.clear()
        this.registryScopeRevision += 1
        this.actionService = dependencies.actionService
        this.dataService = dependencies.dataService
        this.loadedProjectKey = projectKey(this.dataService.getState().project)
        this.actionService.addEventListener(ACTIONS_CHANGED_EVENT, this.handleActionChanged)
        this.actionService.addEventListener(ACTION_DRAFT_CHANGED_EVENT, this.handleActionChanged)
        this.dataService.addEventListener('changed', this.handleDataChanged)
        this.reconcile()
    }

    getSnapshot(): OpenFilesSnapshot {
        return this.snapshot
    }

    getRegisteredDocuments(): readonly OpenDocument[] {
        return [...this.registeredDocuments.values()]
    }

    findDocument(object: OpenDocumentObject): OpenDocument | null {
        return this.registeredDocuments.get(this.scopedObjectKey(object)) ?? null
    }

    openDocument(object: OpenDocumentObject): OpenDocument {
        const document = this.getOrCreateDocument(object)
        if (!this.snapshot.documents.includes(document)) {
            this.update({ activeDocument: document, documents: [...this.snapshot.documents, document] })
        } else {
            this.activateDocument(document)
        }

        return document
    }

    openBoardDocument(object: ProjectCard): CardOpenDocument {
        // Board cards live in the working folder root, so they always carry a stable identity.
        if (!object.header.internalId) throw new Error(`Card identity was not added before opening: ${object.path}`)
        const document = this.getOrCreateDocument(object)
        if (document.kind !== 'card') throw new Error('Board view can only open card documents')

        this.boardDocuments.add(document)

        return document
    }

    openPath(path: string): OpenDocument {
        const object = this.currentObjects().find((candidate) => objectPath(candidate) === path)
        if (!object) throw new Error(`Cannot open unknown document: ${path}`)

        return this.openDocument(object)
    }

    activateDocument(document: OpenDocument) {
        if (!this.snapshot.documents.includes(document) || this.snapshot.activeDocument === document) return

        this.update({ ...this.snapshot, activeDocument: document })
    }

    closeDocument(document: OpenDocument) {
        const index = this.snapshot.documents.indexOf(document)
        if (index === -1) return

        const documents = this.snapshot.documents.filter((candidate) => candidate !== document)
        const activeDocument = this.snapshot.activeDocument === document
            ? documents[index] ?? documents[index - 1] ?? null
            : this.snapshot.activeDocument
        this.update({ activeDocument, documents })
        this.releaseDocument(document as ManagedDocument)
    }

    closeBoardDocument(document: CardOpenDocument) {
        this.boardDocuments.delete(document as ManagedDocument)
        this.releaseDocument(document as ManagedDocument)
    }

    discardDocument(document: OpenDocument) {
        const managedDocument = document as ManagedDocument
        this.boardDocuments.delete(managedDocument)
        const documents = this.snapshot.documents.filter((candidate) => candidate !== document)
        const activeDocument = this.snapshot.activeDocument === document ? documents[0] ?? null : this.snapshot.activeDocument
        if (documents.length !== this.snapshot.documents.length) this.update({ activeDocument, documents })
        this.removeDocument(managedDocument)
    }

    clear() {
        const cleanDocuments = [...this.registeredDocuments.values()].filter((document) => !document.dirty)
        this.boardDocuments.clear()
        if (this.snapshot.documents.length > 0) this.update(EMPTY_SNAPSHOT)
        for (const document of cleanDocuments) this.removeDocument(document)
    }

    private readonly handleActionChanged = () => this.reconcile()
    private readonly handleDataChanged = () => this.reconcile()

    private reconcile() {
        if (!this.actionService || !this.dataService) throw new Error('Open files service is not initialized')
        const { project } = this.dataService.getState()
        const nextProjectKey = projectKey(project)
        if (nextProjectKey !== this.loadedProjectKey) {
            this.loadedProjectKey = nextProjectKey
            this.registryScopeRevision += 1
            this.clear()
        }
        const objects = this.currentObjects()
        const objectsByKey = new Map(objects.map((object) => [this.scopedObjectKey(object), object]))
        for (const [key, document] of this.registeredDocuments) {
            const object = objectsByKey.get(key)
            if (!object) {
                if (!document.dirty) this.removeDocument(document)
                continue
            }
            renewManagedDocument(document, object, this.draftForObject(object))
        }
    }

    private currentObjects() {
        if (!this.actionService || !this.dataService) throw new Error('Open files service is not initialized')
        const { snapshot } = this.dataService.getState()
        const actions = [...this.actionService.getActions(), ...this.actionService.draftStore.getDeletedDraftActions()]

        return snapshotObjects(snapshot, actions)
    }

    private draftForObject(object: OpenDocumentObject): OpenDocumentDraft {
        if (isProjectCard(object)) return object
        if (!object.sourcePath) throw new Error(`Action document requires a source path: ${object.id}`)
        if (!this.actionService) throw new Error('Open files service is not initialized')

        return this.actionService.draftStore.getDraft(object.sourcePath).definition
    }

    private getOrCreateDocument(object: OpenDocumentObject): ManagedDocument {
        const key = this.scopedObjectKey(object)
        const existing = this.registeredDocuments.get(key)
        if (existing) {
            renewManagedDocument(existing, object, this.draftForObject(object))
            return existing
        }

        const draft = this.draftForObject(object)
        const kind = isProjectCard(object) ? 'card' : 'action'
        const document = new ManagedOpenDocument(kind, documentIdentity(object), object, draft) as ManagedDocument
        this.registeredDocuments.set(key, document)
        document.addEventListener('changed', this.handleDocumentChanged)
        this.dispatchDocumentEvent('added', document)

        return document
    }

    private readonly handleDocumentChanged = (event: Event) => {
        const detail = (event as CustomEvent<OpenDocumentChangedDetail>).detail
        this.releaseDocument(detail.document as ManagedDocument)
        if (detail.type === 'renewed' && this.snapshot.documents.includes(detail.document)) {
            this.update({ ...this.snapshot, documents: [...this.snapshot.documents] })
        }
        this.dispatchEvent(new CustomEvent('documentChanged', { detail }))
    }

    private releaseDocument(document: ManagedDocument) {
        if (document.dirty || this.boardDocuments.has(document) || this.snapshot.documents.includes(document)) return

        this.removeDocument(document)
    }

    private removeDocument(document: ManagedDocument) {
        const entry = [...this.registeredDocuments.entries()].find(([, candidate]) => candidate === document)
        if (!entry) return

        document.removeEventListener('changed', this.handleDocumentChanged)
        this.registeredDocuments.delete(entry[0])
        this.boardDocuments.delete(document)
        if (this.snapshot.documents.includes(document)) {
            const documents = this.snapshot.documents.filter((candidate) => candidate !== document)
            const activeDocument = this.snapshot.activeDocument === document ? documents[0] ?? null : this.snapshot.activeDocument
            this.update({ activeDocument, documents })
        }
        this.dispatchDocumentEvent('removed', document)
    }

    private static objectKey(object: OpenDocumentObject) {
        const kind = isProjectCard(object) ? 'card' : 'action'

        return `${kind}:${documentIdentity(object)}`
    }

    private scopedObjectKey(object: OpenDocumentObject) {
        return `${this.registryScopeRevision}:${OpenFilesService.objectKey(object)}`
    }

    private dispatchDocumentEvent(name: 'added' | 'removed', document: OpenDocument) {
        this.dispatchEvent(new CustomEvent<OpenDocumentEventDetail>(name, { detail: { document } }))
    }

    private update(snapshot: OpenFilesSnapshot) {
        if (snapshot.activeDocument === this.snapshot.activeDocument && snapshot.documents === this.snapshot.documents) return

        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<OpenFilesSnapshot>('changed', { detail: snapshot }))
    }
}

export const openFilesService = new OpenFilesService()

const { resolveAgentCommand } = require('../actions/agent/agent_profiles.mjs');

const INTEGRATION_ACTIVITY_LABEL = 'Integrate into project';
const SEARCH_AGENT_PROMPT_PREFIX = 'Return only a single JavaScript-compatible regular expression pattern (no explanation, no surrounding text or markdown) that matches the following search request:\n\n';

function cardIntegrationTracking(request) {
    const hasCardInternalId = Object.hasOwn(request, 'cardInternalId');
    const hasProjectFolder = Object.hasOwn(request, 'projectFolder');
    if (!hasCardInternalId && !hasProjectFolder) return null;
    if (typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
        throw new Error('Missing worktree integration cardInternalId');
    }
    if (typeof request.projectFolder !== 'string') throw new Error('Missing worktree integration projectFolder');

    return { cardInternalId: request.cardInternalId, projectFolder: request.projectFolder };
}

function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}

function resolveSearchAgent(config) {
    const resolved = resolveAgentCommand(config);

    return {
        agent: resolved.agent,
        command: resolved.command,
    };
}

function createLocalBridgeDispatch(dependencies) {
    const {
        actionRunnerService,
        actionSchedulerService,
        agentExecutableAvailability,
        agentRunnerService,
        codexRuntimeService,
        desktopConfigStore,
        diffService,
        localGitService,
        openProjectFolder,
        openWorktreeFolder,
        readDesktopConfig,
        worktreeService,
    } = dependencies;
    let currentLocalProject = null;

    function isCurrentProject(project) {
        return !!currentLocalProject
            && currentLocalProject.branch === project.branch
            && currentLocalProject.id === project.id
            && currentLocalProject.rootPath === project.rootPath;
    }

    async function activateProject(project) {
        if (isCurrentProject(project)) return;

        currentLocalProject = project;
        if (actionSchedulerService) await actionSchedulerService.startProject(project);
        await worktreeService.startProject(project);
    }

    const dataBridge = {
        checkoutBranch: async (project, branch) => {
            const checkedOutProject = await localGitService.checkoutBranch(project, branch);
            await activateProject(checkedOutProject);

            return currentLocalProject;
        },
        cancelActionSchedule: (project, actionsFolder, scheduleId) => {
            if (actionSchedulerService) return actionSchedulerService.cancelActionSchedule(scheduleId);

            return localGitService.cancelActionSchedule(project, actionsFolder, scheduleId);
        },
        commit: async (request) => {
            await localGitService.commit(request, currentLocalProject);

            return [];
        },
        createProject: async (project, workingFolder) => {
            const createdProject = await localGitService.createProject(project, workingFolder);
            await activateProject(createdProject);

            return currentLocalProject;
        },
        deleteFile: (request) => localGitService.deleteFile(request, currentLocalProject),
        deleteFolder: (request) => localGitService.deleteFolder(request, currentLocalProject),
        getActiveProject: () => currentLocalProject,
        hasPendingPush: (project) => localGitService.hasPendingPush(project),
        listBranches: (project) => localGitService.listBranches(project),
        listAgentConversationReferences: (project, projectFolder) => (
            localGitService.listAgentConversationReferences(project, projectFolder)
        ),
        listRepositoryFiles: (project) => localGitService.listRepositoryFiles(project),
        listTopLevelFolders: (project) => localGitService.listTopLevelFolders(project),
        loadActionFiles: (project, actionsFolder) => localGitService.loadActionFiles(project, actionsFolder),
        loadActionSchedules: (project, actionsFolder) => localGitService.loadActionSchedules(project, actionsFolder),
        loadAgentConversation: async (reference) => {
            return localGitService.loadAgentConversation(currentLocalProject, reference);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        loadFile: (project, path) => localGitService.loadFile(project, path),
        loadProjectAsset: (project, path) => localGitService.loadProjectAsset(project, path),
        loadProject: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProject(project, workingFolder);
        },
        loadProjectConfig: (project) => localGitService.loadProjectConfig(project),
        loadProjectRoot: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProjectRoot(project, workingFolder);
        },
        moveFiles: (request) => localGitService.moveFiles(request, currentLocalProject),
        openProjectFolder: async () => {
            if (!openProjectFolder) throw new Error('Project folder picker is not available');

            const rootPath = await openProjectFolder();
            if (!rootPath) return null;

            const project = await localGitService.resolveLocalProject(rootPath);
            await activateProject(project);

            return project;
        },
        addWorktree: async (project) => {
            if (!openWorktreeFolder) throw new Error('Worktree folder picker is not available');

            const folderPath = await openWorktreeFolder();
            if (!folderPath) return false;

            await worktreeService.add(project, folderPath);

            return true;
        },
        prepareWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree preparation request');

            return worktreeService.prepare(request.project, request.worktree, request.branchName);
        },
        commitWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree commit request');

            return worktreeService.commit(request.project, request.worktree, request.message);
        },
        discardWorktreeChanges: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree discard request');

            return worktreeService.discard(request.project, request.worktree);
        },
        integrateWorktree: async (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree integration request');
            const tracking = cardIntegrationTracking(request);
            const integration = await worktreeService.integrate(request.project, request.worktree);
            if (!tracking) return;

            try {
                if (!integration || typeof integration.commit !== 'string' || typeof integration.branch !== 'string') {
                    throw new Error('Worktree integration returned no commit metadata');
                }
                const metadata = await localGitService.resolveCommitMetadata(request.project.rootPath, integration.commit);
                const origin = { cardInternalId: tracking.cardInternalId, kind: 'card' };
                const commit = { ...metadata, branch: integration.branch };
                const record = {
                    commits: [commit],
                    completedAt: metadata.committedAt,
                    label: INTEGRATION_ACTIVITY_LABEL,
                    origin,
                    type: 'system',
                };
                await localGitService.appendAndCommitSystemActivity(
                    request.project,
                    tracking.projectFolder,
                    origin,
                    record,
                    `Record ${INTEGRATION_ACTIVITY_LABEL} activity`,
                );
            } catch (error) {
                throw new Error(`Worktree integrated, but card history tracking failed: ${errorMessage(error)}`, { cause: error });
            }
        },
        parkWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree parking request');

            return worktreeService.park(request.project, request.worktree);
        },
        pullWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree pull request');

            return worktreeService.pull(request.project, request.worktree);
        },
        pull: (project) => worktreeService.pullPrimary(project),
        push: async (project) => {
            await localGitService.push(project);
            await worktreeService.refreshLocal();
        },
        pushWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree push request');

            return worktreeService.push(request.project, request.worktree);
        },
        rebaseWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree rebase request');

            return worktreeService.rebase(request.project, request.worktree);
        },
        onWorktreesChanged: (callback) => worktreeService.subscribe(callback),
        refreshWorktrees: (project) => worktreeService.refreshRemote(project),
        resolveProject: async (project) => {
            const resolvedProject = await localGitService.resolveLocalProject(project.rootPath);
            await activateProject(resolvedProject);

            return resolvedProject;
        },
        saveActionSchedules: (project, actionsFolder, schedules) => localGitService.saveActionSchedules(project, actionsFolder, schedules),
        saveProjectConfig: (project, config) => localGitService.saveProjectConfig(project, config),
        removeWorktree: (project, folderPath) => worktreeService.remove(project, folderPath),
        stopAgent: (runId) => agentRunnerService.stop(runId),
        watchProject: (project, callback) => localGitService.watchProject(project, (event) => {
            if (actionSchedulerService) void actionSchedulerService.handleProjectChange(event);
            callback(event);
        }),
    };

    const actionBridge = {
        answerActionApproval: (executionId, requestId, decision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.answerAgentApproval(executionId, requestId, decision);
        },
        answerActionQuestion: (executionId, requestId, answers) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.answerAgentQuestion(executionId, requestId, answers);
        },
        beginActionPromptDraft: (executionId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.beginAgentPromptDraft(executionId);
        },
        generateDiff: async (request) => {
            const result = await diffService.generateDiff(currentLocalProject, request);

            return { ...result, repositoryRoot: currentLocalProject.rootPath };
        },
        loadActionRunHistory: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            const projectFolder = actionRunnerService.requireProjectFolder();
            const historyRequest = { ...request, projectFolder };

            return localGitService.loadActionRunHistory(currentLocalProject, historyRequest);
        },
        loadActiveActionExecutionEvents: () => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.loadActiveExecutionEvents();
        },
        notifyActionCardStateChange: (cardInternalId, state) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.handleCardStateChange(cardInternalId, state);
        },
        loadCardActivity: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');
            if (!request || typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
                throw new Error('Missing card activity cardInternalId');
            }
            const projectFolder = actionRunnerService.requireProjectFolder();
            const worktrees = worktreeService.getRecords(currentLocalProject);

            return localGitService.loadCardActivity(currentLocalProject, projectFolder, request.cardInternalId, worktrees);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        cancelActionExecution: (executionId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.cancel(executionId);
        },
        finishActionExecution: (executionId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.finishAgentExecution(executionId);
        },
        onActionExecution: (callback) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.subscribe(callback);
        },
        openInEditor: async (request) => diffService.openInEditor(currentLocalProject, request),
        prepareActionPrompt: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.prepareActionPrompt(request);
        },
        readFileAtCommit: (request) => localGitService.readFileAtCommit(currentLocalProject, request),
        registerActionSchedule: (request) => {
            if (!actionSchedulerService) throw new Error('Action scheduler is not available');

            return actionSchedulerService.registerActionSchedule(request);
        },
        runSearchRegexpAgent: async (input, callback) => {
            if (typeof input !== 'string' || input.length === 0) throw new Error('Missing regular expression search input');

            const resolved = resolveSearchAgent(readDesktopConfig(desktopConfigStore));
            const projectConfig = await localGitService.loadProjectConfig(currentLocalProject);
            const projectFolder = typeof projectConfig?.projectFolder === 'string' ? projectConfig.projectFolder : '';
            const request = {
                agent: resolved.agent,
                activityOrigin: { kind: 'project' },
                activityProject: currentLocalProject,
                command: resolved.command,
                prompt: `${SEARCH_AGENT_PROMPT_PREFIX}${input}`,
                projectFolder,
                title: 'Search RegExp',
            };
            const result = await agentRunnerService.run(currentLocalProject, request, callback);

            return result.stdout;
        },
        sendActionMessage: (executionId, content) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendAgentMessage(executionId, content);
        },
        sendActionQueuedMessage: (executionId, sessionId, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendQueuedAgentMessage(executionId, sessionId, revision);
        },
        setActionQueuedMessage: (executionId, sessionId, content, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.setAgentQueuedMessage(executionId, sessionId, content, revision);
        },
        startAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request);
        },
        startUnattendedAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request, { interactive: false });
        },
    };

    const codexRuntimeBridge = {
        getCodexRateLimits: () => codexRuntimeService?.getSnapshot() ?? null,
        onCodexRateLimits: (callback) => {
            if (!codexRuntimeService) throw new Error('Codex runtime service is not available');

            return codexRuntimeService.subscribe(callback);
        },
    };

    const methods = { ...dataBridge, ...actionBridge, ...codexRuntimeBridge };

    return {
        actionBridge,
        codexRuntimeBridge,
        dataBridge,
        invoke: (method, params = []) => {
            const handler = methods[method];
            if (!handler) throw new Error(`Unknown remote-control method: ${method}`);
            if (!Array.isArray(params)) throw new Error('Remote-control params must be an array');

            return handler(...params);
        },
    };
}

module.exports = { createLocalBridgeDispatch };

